"use client";

import { useCallback, useEffect, useId, useLayoutEffect, useMemo, useRef, useState, type ComponentProps, type KeyboardEvent, type ReactNode, type UIEvent } from "react";

import { IconAlertCircle, IconBraces, IconCheck, IconWand } from "@rhs-ui/icons";
import { Button } from "@rhs-ui/primitives/button";
import { countLines, indent, newline, outdent, type Edit } from "@rhs-ui/primitives/code-field/edit";
import { formatJson, positionOf, validateJson, type CodeProblem, type CodeValidation } from "@rhs-ui/primitives/code-field/json";
import { DEFAULT_LABELS, type CodeFieldLabels } from "@rhs-ui/primitives/code-field/labels";
import { Kbd } from "@rhs-ui/primitives/kbd";
import { Textarea } from "@rhs-ui/primitives/textarea";
import { cn } from "@/lib/utils";

export type { CodeProblem, CodeValidation } from "@rhs-ui/primitives/code-field/json";
export type { CodeFieldLabels } from "@rhs-ui/primitives/code-field/labels";

export type CodeLanguage = "json" | "plain";

export interface CodeFieldProps extends Omit<ComponentProps<"textarea">, "value" | "defaultValue" | "onChange" | "children" | "rows" | "wrap"> {
  /** The text, when you control it. */
  value?: string;
  /** The text to start with, when you do not control it. */
  defaultValue?: string;
  /** Called with the whole text on every change, whether it was typed, pasted, indented or formatted. */
  onValueChange?: (value: string) => void;
  /** `json` checks the text after a pause and offers a Format button; `plain` is for CSS, a webhook body or any other text. Default plain. */
  language?: CodeLanguage;
  /** How many lines are visible before it scrolls. Default 10. */
  rows?: number;
  /** Called with the verdict on the text each time the pause after typing ends (`json` only): valid, or the first mistake with its line and column. */
  onValidate?: (result: CodeValidation) => void;
  /** The words the field says, for another language or your own voice. */
  labels?: Partial<CodeFieldLabels>;
}

/** Error text on the tinted bars of this field: a little of the theme's ink in the red keeps it past 4.5:1 where the plain token falls just short. */
const ERROR = "text-[color-mix(in_oklch,var(--destructive),var(--foreground)_14%)]";
/** Fixed pixel metrics, so the line numbers stay on their lines whatever the page's font size. */
const LINE = 22;
const PAD = 10;
/** How long the typing has to stop before the text is checked. */
const PAUSE = 450;

/**
 * A text box for code without an editor library: a monospace face, a gutter of
 * line numbers that scrolls with the text, Tab and Shift+Tab to indent and
 * outdent the selection, and Enter that keeps the indentation. Tab would trap a
 * keyboard user, so Escape followed by Tab leaves the field, and a hint under
 * it says so. With `language="json"` the text is checked after a pause and the
 * first mistake is named with its line and column ("Unexpected token } at line
 * 4, column 3"), the line is marked in the gutter and across the text, and a
 * Format button pretty-prints valid JSON without touching a single digit. A thin
 * row shows line, column and length. There is deliberately no syntax
 * highlighting: the gutter, the indentation and the messages are the value.
 * The helpers `validateJson` and `formatJson` live in `code-field/json`.
 */
export function CodeField({
  value,
  defaultValue = "",
  onValueChange,
  language = "plain",
  rows = 10,
  onValidate,
  labels: labelOverrides,
  readOnly,
  disabled,
  maxLength,
  className,
  onKeyDown,
  onSelect,
  onScroll,
  onFocus,
  onBlur,
  ref,
  "aria-label": ariaLabel,
  "aria-labelledby": labelledBy,
  "aria-describedby": describedBy,
  ...props
}: CodeFieldProps) {
  const uid = useId();
  const hintId = `${uid}-hint`;
  const problemId = `${uid}-problem`;
  const json = language === "json";
  const labels: CodeFieldLabels = { ...DEFAULT_LABELS, ...labelOverrides };
  const [own, setOwn] = useState(defaultValue);
  const text = value ?? own;
  const area = useRef<HTMLTextAreaElement | null>(null);
  // Where the selection should be once the text has been written, when the browser's own editing could not be used.
  const pending = useRef<[number, number] | null>(null);
  const [caret, setCaret] = useState({ start: 0, end: 0, backward: false });
  const [view, setView] = useState({ top: 0, height: rows * LINE + PAD });
  const [focused, setFocused] = useState(false);
  // After Escape the next Tab moves the focus instead of indenting.
  const [escaped, setEscaped] = useState(false);
  const [said, setSaid] = useState("");
  const [settled, setSettled] = useState<{ text: string; result: CodeValidation } | null>(() => (json ? { text, result: validateJson(text) } : null));
  const announced = useRef<string | null>(null);
  const report = useRef(onValidate);

  // The field keeps the ref you pass and uses its own to move the focus.
  const attach = useCallback(
    (node: HTMLTextAreaElement | null) => {
      area.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    },
    [ref],
  );

  useEffect(() => {
    report.current = onValidate;
  });

  // The text is checked once the typing pauses.
  useEffect(() => {
    if (!json || settled?.text === text) return;
    const timer = window.setTimeout(() => setSettled({ text, result: validateJson(text) }), PAUSE);
    return () => window.clearTimeout(timer);
  }, [json, text, settled]);

  const result = json ? (settled?.result ?? null) : null;

  useEffect(() => {
    if (!result) return;
    report.current?.(result);
    const sentence = result.valid ? (result.empty ? "" : labels.valid) : result.message;
    // The first verdict is what was there from the start; only a change is news.
    if (announced.current !== null && announced.current !== sentence) setSaid(sentence);
    announced.current = sentence;
  }, [result]);

  // What a screen reader was told stays only while it is news; the region is read as a whole.
  useEffect(() => {
    if (!said) return;
    const timer = window.setTimeout(() => setSaid(""), 4000);
    return () => window.clearTimeout(timer);
  }, [said]);

  // The gutter and the marked line need to know how much of the text is in view.
  useEffect(() => {
    const element = area.current;
    if (!element || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => setView((now) => (now.height === element.clientHeight ? now : { ...now, height: element.clientHeight })));
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  function track() {
    const node = area.current;
    if (!node) return;
    setCaret((now) =>
      now.start === node.selectionStart && now.end === node.selectionEnd ? now : { start: node.selectionStart, end: node.selectionEnd, backward: node.selectionDirection === "backward" },
    );
  }

  useLayoutEffect(() => {
    const selection = pending.current;
    if (!selection) return;
    pending.current = null;
    area.current?.setSelectionRange(selection[0], selection[1]);
    track();
  });

  function write(next: string) {
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  }

  function apply(edit: Edit) {
    const node = area.current;
    if (!node) return;
    const next = text.slice(0, edit.from) + edit.text + text.slice(edit.to);
    if (maxLength !== undefined && next.length > maxLength && next.length > text.length) return;
    node.focus();
    node.setSelectionRange(edit.from, edit.to);
    // insertText and delete are edits the browser knows about, so Ctrl or Cmd+Z undoes an indent the way it undoes typing.
    let done = false;
    try {
      done = edit.text === "" ? document.execCommand("delete") : document.execCommand("insertText", false, edit.text);
    } catch {
      done = false;
    }
    if (done) {
      node.setSelectionRange(edit.start, edit.end);
      track();
    } else {
      pending.current = [edit.start, edit.end];
      write(next);
    }
  }

  function goTo(problem: CodeProblem) {
    const node = area.current;
    if (!node) return;
    node.focus({ preventScroll: true });
    node.setSelectionRange(problem.offset, problem.offset);
    node.scrollTop = Math.max(0, (problem.line - 1) * LINE - node.clientHeight / 2 + LINE);
    track();
  }

  function format() {
    const formatted = formatJson(text);
    if (formatted === null) {
      // Do not wait for the pause: whoever pressed Format wants the reason now.
      const now = validateJson(text);
      setSettled({ text, result: now });
      if (!now.valid) goTo(now);
      return;
    }
    if (formatted === text) {
      setSaid(labels.saidAlready);
      return;
    }
    apply({ from: 0, to: text.length, text: formatted, start: 0, end: 0 });
    setSaid(labels.saidFormatted);
  }

  function keyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    onKeyDown?.(event);
    if (event.defaultPrevented || event.nativeEvent.isComposing || readOnly || disabled) return;
    const { key } = event;
    // A modifier on its own is the first half of Shift+Tab, not a key that ends the escape.
    if (key === "Shift" || key === "Control" || key === "Alt" || key === "Meta") return;
    if (key === "Escape") {
      if (!escaped) {
        setEscaped(true);
        setSaid(labels.saidEscaped);
      }
      return;
    }
    const node = event.currentTarget;
    if (key === "Tab" && !event.ctrlKey && !event.metaKey && !event.altKey) {
      // The Tab right after Escape is the browser's own.
      if (escaped) {
        setEscaped(false);
        return;
      }
      event.preventDefault();
      const edit = event.shiftKey ? outdent(text, node.selectionStart, node.selectionEnd) : indent(text, node.selectionStart, node.selectionEnd);
      if (edit) apply(edit);
      return;
    }
    if (escaped) setEscaped(false);
    if (key === "Enter" && !event.shiftKey && !event.metaKey && !event.ctrlKey && !event.altKey) {
      event.preventDefault();
      apply(newline(text, node.selectionStart, node.selectionEnd));
    }
  }

  const lineCount = useMemo(() => countLines(text), [text]);
  const here = useMemo(() => positionOf(text, caret.backward ? caret.start : caret.end), [text, caret]);
  const problem = result && !result.valid ? result : null;
  const selected = caret.end - caret.start;
  const digits = Math.max(2, String(lineCount).length);
  const first = Math.max(0, Math.floor(view.top / LINE) - 1);
  const last = Math.min(lineCount, first + Math.ceil(view.height / LINE) + 3);
  const current = focused && caret.start === caret.end ? here.line : 0;
  const bandTop = (line: number) => PAD + (line - 1) * LINE - view.top;
  const named = props.id !== undefined || ariaLabel !== undefined || labelledBy !== undefined;

  const gutter: ReactNode[] = [];
  for (let index = first; index < last; index += 1) {
    const line = index + 1;
    const marked = problem?.line === line;
    gutter.push(
      <div
        key={line}
        data-problem={marked || undefined}
        className={cn("flex h-[22px] items-center justify-end gap-1.5 pr-2.5 pl-2 tabular-nums", marked ? cn("bg-destructive/10 font-semibold", ERROR) : line === current && "font-medium text-foreground")}
      >
        {marked ? <span className="size-1.5 shrink-0 rounded-full bg-destructive" /> : null}
        <span>{line}</span>
      </div>,
    );
  }

  return (
    <div data-slot="code-field" className={cn("w-full min-w-0", className)}>
      <div
        className={cn(
          "overflow-hidden rounded-md border border-input bg-background shadow-xs transition-[border-color,box-shadow] duration-150 motion-reduce:transition-none",
          "has-[textarea:focus-visible]:border-ring has-[textarea:focus-visible]:ring-[3px] has-[textarea:focus-visible]:ring-ring/40",
          disabled && "opacity-50",
        )}
      >
        {json ? (
          <div className="flex items-center justify-between gap-2 border-b border-border bg-muted/40 py-1 pr-1.5 pl-3">
            <span className="inline-flex items-center gap-1.5 text-xs font-medium text-muted-foreground">
              <IconBraces aria-hidden="true" className="size-3.5" />
              {labels.languageJson}
            </span>
            {readOnly ? null : (
              <Button type="button" variant="ghost" size="sm" disabled={disabled || text.trim() === ""} onClick={format} className="h-7 gap-1.5 px-2 text-xs">
                <IconWand aria-hidden="true" className="size-3.5" />
                {labels.format}
              </Button>
            )}
          </div>
        ) : null}
        <div className="flex min-w-0 items-stretch">
          <div aria-hidden="true" className="relative shrink-0 overflow-hidden border-r border-border bg-muted/40 font-mono text-xs text-muted-foreground select-none" style={{ width: `calc(${digits}ch + 1.75rem)` }}>
            {/* The numbers are clipped to the height of the text, so the strip under the last line stays empty. */}
            <div className="absolute inset-x-0 top-0 overflow-hidden" style={{ height: view.height }}>
              <div style={{ transform: `translateY(${PAD + first * LINE - view.top}px)` }}>{gutter}</div>
            </div>
          </div>
          {/* The bottom breathing room is outside the textarea: padding inside it would show the top of the next line. */}
          <div className="relative flex min-w-0 flex-1 cursor-text pb-[10px]">
            <div aria-hidden="true" className="pointer-events-none absolute inset-x-0 top-0 overflow-hidden" style={{ height: view.height }}>
              {current > 0 && current !== problem?.line && bandTop(current) > -LINE && bandTop(current) < view.height ? (
                <div className="absolute inset-x-0 h-[22px] bg-foreground/[0.04]" style={{ top: bandTop(current) }} />
              ) : null}
              {problem && bandTop(problem.line) > -LINE && bandTop(problem.line) < view.height ? <div className="absolute inset-x-0 h-[22px] bg-destructive/10" style={{ top: bandTop(problem.line) }} /> : null}
            </div>
            <Textarea
              {...props}
              ref={attach}
              rows={rows}
              wrap="off"
              spellCheck={false}
              autoCapitalize="off"
              autoCorrect="off"
              autoComplete="off"
              readOnly={readOnly}
              disabled={disabled}
              maxLength={maxLength}
              value={text}
              aria-label={named ? ariaLabel : json ? labels.jsonName : labels.codeName}
              aria-labelledby={labelledBy}
              aria-invalid={problem ? true : undefined}
              aria-describedby={[describedBy, readOnly || disabled ? "" : hintId, problem ? problemId : ""].filter(Boolean).join(" ") || undefined}
              onChange={(event) => {
                write(event.target.value);
                track();
              }}
              onKeyDown={keyDown}
              onSelect={(event) => {
                onSelect?.(event);
                track();
              }}
              onFocus={(event) => {
                onFocus?.(event);
                setFocused(true);
                track();
              }}
              onBlur={(event) => {
                onBlur?.(event);
                setFocused(false);
                setEscaped(false);
              }}
              onScroll={(event: UIEvent<HTMLTextAreaElement>) => {
                onScroll?.(event);
                // Read now: by the time the updater runs the event no longer has its target.
                const top = event.currentTarget.scrollTop;
                setView((now) => (now.top === top ? now : { ...now, top }));
              }}
              className="relative block min-w-0 flex-1 resize-y overflow-auto field-sizing-fixed max-h-none min-h-0 rounded-none border-0 bg-transparent px-3 pt-[10px] pb-0 font-mono text-[13px] leading-[22px] whitespace-pre shadow-none [tab-size:2] focus-visible:border-0 focus-visible:ring-0 disabled:opacity-100"
            />
          </div>
        </div>
        {problem ? (
          <div id={problemId} className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1.5 border-t border-border bg-destructive/5 px-3 py-2 text-xs">
            <p className={cn("flex min-w-0 items-start gap-1.5", ERROR)}>
              <IconAlertCircle aria-hidden="true" className="mt-px size-3.5 shrink-0" />
              <span className="min-w-0 [overflow-wrap:anywhere]">{problem.message}</span>
            </p>
            <button
              type="button"
              onClick={() => goTo(problem)}
              className="-mx-0.5 rounded-sm px-0.5 font-medium text-foreground underline decoration-foreground/30 underline-offset-4 outline-none hover:decoration-foreground focus-visible:ring-[3px] focus-visible:ring-ring/40"
            >
              {labels.goTo(problem.line)}
            </button>
          </div>
        ) : null}
        <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-1 border-t border-border bg-muted/40 px-3 py-1.5 text-xs text-muted-foreground tabular-nums">
          <p className="flex flex-wrap items-center gap-x-2 gap-y-0.5">
            <span>{labels.position(here.line, here.column, selected)}</span>
            <span aria-hidden="true">&middot;</span>
            <span>{labels.characters(text.length)}</span>
          </p>
          {result ? (
            result.valid ? (
              <span className={cn("inline-flex items-center gap-1", !result.empty && "text-foreground")}>
                {result.empty ? null : <IconCheck aria-hidden="true" className="size-3.5" />}
                {result.empty ? labels.empty : labels.valid}
              </span>
            ) : (
              <span className={cn("inline-flex items-center gap-1 font-medium", ERROR)}>
                <IconAlertCircle aria-hidden="true" className="size-3.5" />
                {labels.invalid}
              </span>
            )
          ) : null}
        </div>
      </div>
      {readOnly || disabled ? null : (
        <p id={hintId} className="mt-2 flex flex-wrap items-center gap-x-1.5 gap-y-1 text-xs text-muted-foreground">
          {escaped ? (
            <span className="font-medium text-foreground">{labels.hintEscaped}</span>
          ) : (
            <>
              <Kbd>Tab</Kbd>
              <span>{labels.hintIndents}</span>
              <Kbd>Esc</Kbd>
              <span>{labels.hintThen}</span>
              <Kbd>Tab</Kbd>
              <span>{labels.hintLeaves}</span>
            </>
          )}
        </p>
      )}
      <span role="status" className="sr-only">
        {said}
      </span>
    </div>
  );
}

/** What is wrong in a piece of JSON and where. `line` and `column` count from 1; `offset` is the position between characters, for putting the caret there. */
export interface CodeProblem {
  /** A sentence that ends with the place: "Unexpected token } at line 4, column 3". */
  message: string;
  line: number;
  column: number;
  offset: number;
}

/** The verdict on a text: fine (`empty` when there is nothing in it yet), or the first mistake in it. */
export type CodeValidation = { valid: true; empty: boolean } | ({ valid: false } & CodeProblem);

/** `word` is a run of letters that is not true, false or null: wrong as a value, and as a property name it is a key that lacks its quotes. */
type TokenKind = "punct" | "string" | "number" | "literal" | "word";

interface Token {
  kind: TokenKind;
  text: string;
  start: number;
  end: number;
}

/** A mistake found while reading: what it is, and where it is as a position between characters. */
class Mistake extends Error {
  offset: number;

  constructor(reason: string, offset: number) {
    super(reason);
    this.offset = offset;
  }
}

const fail = (reason: string, offset: number): never => {
  throw new Mistake(reason, offset);
};

const MAX_DEPTH = 200;
const isDigit = (char: string) => char >= "0" && char <= "9";
const isWord = (char: string) => /[A-Za-z_$]/.test(char);
const isPunct = (token: Token | null, text: string): boolean => token !== null && token.kind === "punct" && token.text === text;
const startsValue = (token: Token) => token.kind !== "punct" || token.text === "{" || token.text === "[";

/** Words people write by habit that JSON does not have, with what to write instead. */
const WORDS: Record<string, string> = {
  undefined: "undefined is not valid JSON, use null",
  NaN: "NaN is not valid JSON, use null",
  Infinity: "Infinity is not valid JSON, use null",
  True: "Write true in lower case",
  False: "Write false in lower case",
  Null: "Write null in lower case",
  None: "None is not valid JSON, use null",
};

/** A character nobody can see on a screen: any kind of space, a control character, a zero-width or direction mark, a byte order mark. */
const UNSEEN = /[\s\p{Cc}\p{Cf}]/u;

/** What the message calls the character it stopped at: the character itself when it can be seen, otherwise a name, or its code point, so a pasted non-breaking space or byte order mark does not read as "Unexpected token " with nothing behind it. */
function describeToken(char: string): string {
  const code = char.codePointAt(0) ?? 0;
  if (code === 0xa0) return "Unexpected non-breaking space";
  if (code === 0xfeff) return "Unexpected byte order mark";
  if (code === 0x200b) return "Unexpected zero-width space";
  if (UNSEEN.test(char)) return `Unexpected character U+${code.toString(16).toUpperCase().padStart(4, "0")}`;
  return `Unexpected token ${char}`;
}

/** Reads one token at a time, so that a mistake is reported in the order it appears in the text, whether it is in a word or in the structure. */
class Lexer {
  readonly tokens: Token[] = [];
  /** Where the token before the last one read ends: a missing comma belongs there. */
  before = 0;
  /** Where the last token read ends: a value that never comes is missing there. */
  end = 0;
  private text: string;
  private at = 0;
  private ahead: Token | null | undefined;

  constructor(text: string) {
    this.text = text;
  }

  peek(): Token | null {
    if (this.ahead === undefined) this.ahead = this.read();
    return this.ahead;
  }

  next(): Token | null {
    const token = this.peek();
    this.ahead = undefined;
    if (token) {
      this.before = this.end;
      this.end = token.end;
      this.tokens.push(token);
    }
    return token;
  }

  private read(): Token | null {
    const { text } = this;
    while (this.at < text.length && " \t\n\r".includes(text.charAt(this.at))) this.at += 1;
    if (this.at >= text.length) return null;
    const start = this.at;
    const char = text.charAt(start);
    let end: number;
    let kind: TokenKind;
    if ("{}[],:".includes(char)) {
      end = start + 1;
      kind = "punct";
    } else if (char === '"') {
      end = this.string(start);
      kind = "string";
    } else if (char === "'") {
      return fail("Strings need double quotes, not single quotes", start);
    } else if (char === "/" && (text.charAt(start + 1) === "/" || text.charAt(start + 1) === "*")) {
      return fail("JSON does not allow comments", start);
    } else if (char === "-" || isDigit(char)) {
      end = this.number(start);
      kind = "number";
    } else if (isWord(char)) {
      end = start + 1;
      while (end < text.length && /[\w$]/.test(text.charAt(end))) end += 1;
      const word = text.slice(start, end);
      kind = word === "true" || word === "false" || word === "null" ? "literal" : "word";
    } else {
      // A whole code point, so an emoji is named as itself and not as half of a surrogate pair.
      return fail(describeToken(String.fromCodePoint(text.codePointAt(start) ?? 0)), start);
    }
    this.at = end;
    return { kind, text: text.slice(start, end), start, end };
  }

  /** The end of the string that starts at `start`. */
  private string(start: number): number {
    const { text } = this;
    let at = start + 1;
    while (at < text.length) {
      const char = text.charAt(at);
      if (char === '"') return at + 1;
      if (char === "\\") {
        const escaped = text.charAt(at + 1);
        if (escaped === "u") {
          if (!/^[\da-fA-F]{4}$/.test(text.slice(at + 2, at + 6))) fail("Invalid \\u escape in a string", at);
          at += 6;
        } else if (escaped !== "" && '"\\/bfnrt'.includes(escaped)) {
          at += 2;
        } else {
          return fail(escaped === "" ? "String is not closed" : `Invalid escape \\${escaped} in a string`, escaped === "" ? start : at);
        }
        continue;
      }
      if (char === "\n" || char === "\r") return fail("String is not closed before the end of the line", start);
      if (char < " ") return fail("Control characters in a string must be escaped", at);
      at += 1;
    }
    return fail("String is not closed", start);
  }

  /** The end of the number that starts at `start`. */
  private number(start: number): number {
    const { text } = this;
    let at = start;
    if (text.charAt(at) === "-") at += 1;
    if (text.charAt(at) === "0") {
      at += 1;
      if (isDigit(text.charAt(at))) fail("Numbers cannot start with a zero", start);
    } else if (isDigit(text.charAt(at))) {
      while (isDigit(text.charAt(at))) at += 1;
    } else {
      fail("A minus sign needs digits behind it", start);
    }
    if (text.charAt(at) === ".") {
      at += 1;
      if (!isDigit(text.charAt(at))) fail("A number needs digits after the decimal point", at - 1);
      while (isDigit(text.charAt(at))) at += 1;
    }
    if (text.charAt(at) === "e" || text.charAt(at) === "E") {
      at += 1;
      if (text.charAt(at) === "+" || text.charAt(at) === "-") at += 1;
      if (!isDigit(text.charAt(at))) fail("An exponent needs digits", at - 1);
      while (isDigit(text.charAt(at))) at += 1;
    }
    return at;
  }
}

const unclosed = (open: Token) => new Mistake(`Missing ${open.text === "{" ? "}" : "]"} for the ${open.text}`, open.start);

function value(lexer: Lexer, depth: number): void {
  const token = lexer.next();
  if (!token) throw new Mistake("Unexpected end of the JSON", lexer.end);
  if (token.kind === "word") fail(WORDS[token.text] ?? `Unexpected "${token.text}"`, token.start);
  if (token.kind !== "punct") return;
  if (token.text === "{") return object(lexer, token, depth + 1);
  if (token.text === "[") return array(lexer, token, depth + 1);
  fail(`Unexpected token ${token.text}`, token.start);
}

function object(lexer: Lexer, open: Token, depth: number): void {
  if (depth > MAX_DEPTH) fail("Nested too deeply", open.start);
  if (isPunct(lexer.peek(), "}")) {
    lexer.next();
    return;
  }
  let comma: Token | null = null;
  for (;;) {
    const key = lexer.next();
    if (!key) throw unclosed(open);
    if (isPunct(key, "}") && comma) fail("Trailing comma before }", comma.start);
    if (key.kind !== "string") fail("Expected a property name in double quotes", key.start);
    const colon = lexer.next();
    if (!colon) throw unclosed(open);
    if (!isPunct(colon, ":")) fail("Expected : after the property name", colon.start);
    value(lexer, depth);
    const after = lexer.next();
    if (!after) throw unclosed(open);
    if (isPunct(after, "}")) return;
    if (isPunct(after, ",")) {
      comma = after;
      continue;
    }
    fail(startsValue(after) ? "Missing comma" : `Expected , or } but found ${after.text}`, startsValue(after) ? lexer.before : after.start);
  }
}

function array(lexer: Lexer, open: Token, depth: number): void {
  if (depth > MAX_DEPTH) fail("Nested too deeply", open.start);
  if (isPunct(lexer.peek(), "]")) {
    lexer.next();
    return;
  }
  let comma: Token | null = null;
  for (;;) {
    const first = lexer.peek();
    if (!first) throw unclosed(open);
    if (isPunct(first, "]") && comma) fail("Trailing comma before ]", comma.start);
    value(lexer, depth);
    const after = lexer.next();
    if (!after) throw unclosed(open);
    if (isPunct(after, "]")) return;
    if (isPunct(after, ",")) {
      comma = after;
      continue;
    }
    fail(startsValue(after) ? "Missing comma" : `Expected , or ] but found ${after.text}`, startsValue(after) ? lexer.before : after.start);
  }
}

/** The line and column (both from 1) of a position between characters. */
export function positionOf(text: string, offset: number): { line: number; column: number } {
  let line = 1;
  let lineStart = 0;
  const stop = Math.min(offset, text.length);
  for (let at = text.indexOf("\n"); at !== -1 && at < stop; at = text.indexOf("\n", at + 1)) {
    line += 1;
    lineStart = at + 1;
  }
  return { line, column: stop - lineStart + 1 };
}

/** Reads the whole text as one JSON value, and throws the first mistake. */
function read(text: string): Lexer {
  const lexer = new Lexer(text);
  value(lexer, 0);
  const extra = lexer.next();
  if (extra) fail("Unexpected content after the end of the JSON", extra.start);
  return lexer;
}

/**
 * Checks a text as JSON and names the first mistake with its line and column,
 * in plain words and the same words in every browser: a trailing comma, a
 * missing comma, single quotes, a comment, an unclosed bracket. It does not
 * depend on the message JSON.parse gives, which differs from one engine to
 * the next. A text with nothing in it is not a mistake.
 */
export function validateJson(text: string): CodeValidation {
  if (text.trim() === "") return { valid: true, empty: true };
  try {
    read(text);
    return { valid: true, empty: false };
  } catch (error) {
    if (!(error instanceof Mistake)) throw error;
    const { line, column } = positionOf(text, error.offset);
    return { valid: false, message: `${error.message} at line ${line}, column ${column}`, line, column, offset: error.offset };
  }
}

/**
 * Pretty-prints valid JSON, one level of `indent` per depth, or returns null
 * when the text is not valid. It works on the tokens and not on parsed
 * values, so a number such as 12345678901234567890 or 1.50 keeps every digit
 * it was written with, and the order of the keys is untouched.
 */
export function formatJson(text: string, indent = "  "): string | null {
  if (text.trim() === "") return null;
  let tokens: Token[];
  try {
    tokens = read(text).tokens;
  } catch (error) {
    if (error instanceof Mistake) return null;
    throw error;
  }
  let out = "";
  let depth = 0;
  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];
    if (!token) continue;
    if (token.kind !== "punct") {
      out += token.text;
    } else if (token.text === "{" || token.text === "[") {
      const next = tokens[index + 1];
      if (next && next.kind === "punct" && (next.text === "}" || next.text === "]")) {
        out += token.text + next.text;
        index += 1;
      } else {
        depth += 1;
        out += `${token.text}\n${indent.repeat(depth)}`;
      }
    } else if (token.text === "}" || token.text === "]") {
      depth -= 1;
      out += `\n${indent.repeat(depth)}${token.text}`;
    } else if (token.text === ",") {
      out += `,\n${indent.repeat(depth)}`;
    } else {
      out += ": ";
    }
  }
  return out;
}

/** A change to make: the characters from `from` to `to` become `text`, and afterwards `start` to `end` is selected (positions in the changed text). */
export interface Edit {
  from: number;
  to: number;
  text: string;
  start: number;
  end: number;
}

/** One level of indentation: two spaces. */
export const INDENT = "  ";

const lineStartOf = (value: string, at: number) => value.lastIndexOf("\n", at - 1) + 1;

const lineEndOf = (value: string, at: number) => {
  const found = value.indexOf("\n", at);
  return found === -1 ? value.length : found;
};

/** How many lines a text has: one more than its line breaks. */
export function countLines(value: string): number {
  let lines = 1;
  for (let at = value.indexOf("\n"); at !== -1; at = value.indexOf("\n", at + 1)) lines += 1;
  return lines;
}

/** The lines a selection touches, from the start of the first to the end of the last. A selection that ends right after a line break does not touch the line behind it. */
function touched(value: string, start: number, end: number): { from: number; to: number; lines: string[] } {
  const from = lineStartOf(value, start);
  const last = end > start && value.charAt(end - 1) === "\n" ? end - 1 : end;
  const to = lineEndOf(value, last);
  return { from, to, lines: value.slice(from, to).split("\n") };
}

/**
 * What Tab does. With nothing selected it moves to the next tab stop with
 * spaces; with a selection it indents every line the selection touches (blank
 * lines stay blank) and keeps the selection, so Tab never replaces the text
 * that is selected.
 */
export function indent(value: string, start: number, end: number): Edit {
  if (start === end) {
    const column = start - lineStartOf(value, start);
    const pad = " ".repeat(INDENT.length - (column % INDENT.length));
    return { from: start, to: end, text: pad, start: start + pad.length, end: start + pad.length };
  }
  const { from, to, lines } = touched(value, start, end);
  const added = lines.map((line) => (line.trim() === "" ? 0 : INDENT.length));
  const text = lines.map((line, index) => (added[index] ? INDENT + line : line)).join("\n");
  const total = added.reduce((sum, count) => sum + count, 0);
  return { from, to, text, start: start === from ? start : start + (added[0] ?? 0), end: end + total };
}

/**
 * What Shift+Tab does: takes one level of indentation (up to two spaces, or a
 * tab) off every line the selection touches. Null when there is nothing to
 * take off.
 */
export function outdent(value: string, start: number, end: number): Edit | null {
  const { from, to, lines } = touched(value, start, end);
  const removed = lines.map((line) => (line.startsWith("\t") ? 1 : Math.min(INDENT.length, (/^ */.exec(line)?.[0] ?? "").length)));
  const total = removed.reduce((sum, count) => sum + count, 0);
  if (total === 0) return null;
  const text = lines.map((line, index) => line.slice(removed[index] ?? 0)).join("\n");
  /** Where a position in the old text is in the new one. */
  const moved = (position: number) => {
    if (position > to) return position - total;
    let offset = from;
    let taken = 0;
    for (let index = 0; index < lines.length; index += 1) {
      const length = lines[index]?.length ?? 0;
      if (position <= offset + length) return position - taken - Math.min(removed[index] ?? 0, position - offset);
      offset += length + 1;
      taken += removed[index] ?? 0;
    }
    return position - total;
  };
  return { from, to, text, start: moved(start), end: moved(end) };
}

const CLOSERS: Record<string, string> = { "{": "}", "[": "]", "(": ")" };

/**
 * What Enter does: the new line starts at the indentation of the line it was
 * pressed on, one level deeper behind an opening bracket, and between a pair
 * of brackets the closing one drops to a line of its own with the caret on the
 * line between.
 */
export function newline(value: string, start: number, end: number): Edit {
  const from = lineStartOf(value, start);
  const before = value.slice(from, start);
  const lead = /^[ \t]*/.exec(before)?.[0] ?? "";
  const opener = before.trimEnd().slice(-1);
  const opens = opener in CLOSERS;
  const inner = lead + (opens ? INDENT : "");
  if (opens && value.charAt(end) === CLOSERS[opener]) {
    const caret = start + 1 + inner.length;
    return { from: start, to: end, text: `\n${inner}\n${lead}`, start: caret, end: caret };
  }
  const text = `\n${inner}`;
  return { from: start, to: end, text, start: start + text.length, end: start + text.length };
}

/**
 * The words the field says, for another language or your own voice. Each can be
 * replaced. The messages that name a mistake in the JSON ("Unexpected token }
 * at line 4, column 3") come from the checker and are in English; show your
 * own from `onValidate` if you need them in another language.
 */
export interface CodeFieldLabels {
  /** The name of a JSON field for a screen reader when it has no label, id or aria-label of its own. */
  jsonName: string;
  /** The name of any other field for a screen reader when it has no label, id or aria-label of its own. */
  codeName: string;
  /** The label above the field's language, on the bar that holds the Format button. */
  languageJson: string;
  /** The button that pretty-prints valid JSON. */
  format: string;
  /** The verdict on valid JSON, in the status row. */
  valid: string;
  /** The verdict on JSON with a mistake. */
  invalid: string;
  /** The verdict on a text with nothing in it. */
  empty: string;
  /** The link in the message that puts the caret at the mistake. */
  goTo: (line: number) => string;
  /** Where the caret is, in the status row; `selected` is how many characters are selected. */
  position: (line: number, column: number, selected: number) => string;
  /** How long the text is. */
  characters: (count: number) => string;
  /** The hint under the field, after the Tab key: "indents." */
  hintIndents: string;
  /** The hint, between the Esc key and the Tab key: "then". */
  hintThen: string;
  /** The hint, after the second Tab key: "leaves the field." */
  hintLeaves: string;
  /** The hint while the next Tab is the browser's own. */
  hintEscaped: string;
  /** What a screen reader hears after Escape. */
  saidEscaped: string;
  /** What a screen reader hears after Format. */
  saidFormatted: string;
  /** What a screen reader hears after Format on text that is formatted already. */
  saidAlready: string;
}

export const DEFAULT_LABELS: CodeFieldLabels = {
  jsonName: "JSON",
  codeName: "Code",
  languageJson: "JSON",
  format: "Format",
  valid: "Valid JSON",
  invalid: "Invalid JSON",
  empty: "Empty",
  goTo: (line) => `Go to line ${line}`,
  position: (line, column, selected) => `Ln ${line}, Col ${column}${selected > 0 ? ` (${selected} selected)` : ""}`,
  characters: (count) => `${count} ${count === 1 ? "character" : "characters"}`,
  hintIndents: "indents.",
  hintThen: "then",
  hintLeaves: "leaves the field.",
  hintEscaped: "Tab now leaves the field.",
  saidEscaped: "Tab now moves the focus out of the field.",
